#include <set>
#include <vector>
#include <iostream>

int main() {
    std::set<int> s;

    // Standard O(log N) insertion
    s.insert(50);

    // Optimized O(1) insertion using hint
    // 'it' is likely near the correct spot for 51
    auto it = s.insert(50).first;
    it = s.insert(it, 51); // O(1) if successful
    it = s.insert(it, 52); // O(1) if successful

    // Range insertion optimization
    std::vector<int> sorted_data = {1, 2, 3};
    s.insert(sorted_data.begin(), sorted_data.end()); 
    // Often faster than repeated single inserts.
}
